            prev_bids.append(prev.get('bid', 0.0))
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
            urgent_opp += 1
        if opp.get('budget', 0) >= 700:
            rich_opp += 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    my_urgent = hp <= 3 or no_water_days >= 2
    my_semi_urgent = hp <= 5 or no_water_days >= 1

    if my_urgent:
        target = max(95.0, highest_prev + 3.0)
        if rich_opp >= 2:
            target = max(target, 112.0)
        if supply <= 17:
            target += 10.0
    elif my_semi_urgent:
        target = 62.0 + 28.0 * scarcity
        if highest_prev >= 100.0:
            target = max(target, highest_prev - 6.0)
        elif highest_prev >= 75.0:
            target = max(target, highest_prev - 10.0)
    else:
        if supply >= 22:
            target = 18.0 + 6.0 * scarcity
        elif supply >= 19:
            target = 26.0 + 10.0 * scarcity
        else:
            target = 38.0 + 18.0 * scarcity

        if avg_prev >= 120.0:
            target = min(target, 42.0)
        elif avg_prev >= 85.0 and supply >= 20:
            target = min(target, 36.0)

        if urgent_opp >= 2 and supply <= 18:
            target += 8.0

    if day >= 8:
        target += 6.0 if my_semi_urgent else 2.0

    if budget < 120:
        target = min(target, budget * 0.72)
    elif budget < 220:
        target = min(target, budget * 0.82)
    else:
        target = min(target, budget * 0.9)

    if target < 0:
        target = 0.0
    if target > budget:
        target = budget

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context.get('supply', 0)
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        try:
            if o.get('alive', False):
                alive_opps.append((oid, o))
        except Exception:
            continue

    # If no opponents, bid a conservative amount
    if not alive_opps:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    prev_bids = []
    prev_by_opp = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b_val = float(b)
                prev_bids.append(b_val)
                prev_by_opp[oid] = b_val
            except Exception:
                pass

    # Estimate required intensity based on supply level (mid scenario)
    # Higher supply means less need to overbid; lower supply means more.
    # Use thresholds around the given range.
    try:
        s = float(supply)
    except Exception:
        s = float(MIN_SUPPLY)

    if s <= (MIN_SUPPLY + 1.0):
        supply_pressure = 1.0
    elif s >= (MAX_SUPPLY - 1.0):
        supply_pressure = 0.4
    else:
        supply_pressure = 0.7

    # Determine target bid based on yesterday's strongest bid
    if prev_bids:
        strongest = max(prev_bids)
        second = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else strongest

        # If opponent bids were high, they likely secured water; we must compete.
        # Cindy had highest average and survived; treat strongest as likely winner.
        # Beat by a small increment scaled by supply pressure.
        beat = 2.0 + 6.0 * supply_pressure

        # If our hp is low, increase aggressiveness to avoid death.
        hp = float(my_status.get('hp', 0))
        no_water_days = int(my_status.get('no_water_days', 0))

        # Aggression factor
        if hp <= 1.5 or no_water_days >= 2:
            urgency = 1.0
        elif hp <= 3.5:
            urgency = 0.8
        else:
            urgency = 0.55

        target = strongest + beat * urgency

        # Don't overpay beyond a fraction of budget; also cap relative to strongest
        # Budget safety: if budget is very low, bid what we can.
        budget = float(my_status.get('budget', 0))
        if budget <= 0:
            return 0.0

        # If strongest was extremely high, we may not be able to match; still bid a meaningful amount.
        # Use a floor to avoid bidding too low when supply is tight.
        min_bid = DAILY_SALARY * (0.35 + 0.35 * supply_pressure)
        # Use a cap to avoid draining budget.
        cap_bid = budget * (0.35 + 0.35 * urgency)

        bid = float(min(max(target, min_bid), cap_bid))
        return bid

    # Fallback when no previous bids available
    hp = float(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0))
    if budget <= 0:
        return 0.0

    if hp <= 2.0:
        return float(min(budget, DAILY_SALARY * 0.9))
    return float(min(budget, DAILY_SALARY * (0.5 + 0.3 * supply_pressure)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    num_active_players = len(alive_opponents) + 1
    is_supply_tight = day_context['supply'] < (num_active_players * WATER_REQ * 1.2)

    bid = DAILY_SALARY * 0.55 # Default moderate bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.8: # High competition (e.g., Alex)
            if my_status['hp'] > 5: 
                if is_supply_tight:
                    bid = min(DAILY_SALARY * 0.9, highest_prev_bid + 5)
                else:
                    bid = DAILY_SALARY * 0.7
            else: # Low HP, need water desperately
                bid = min(DAILY_SALARY * 0.98, highest_prev_bid + 10)
        elif highest_prev_bid >= DAILY_SALARY * 0.6: # Moderate competition (e.g., Eric)
            if is_supply_tight:
                bid = max(DAILY_SALARY * 0.7, highest_prev_bid + 2)
            else:
                bid = DAILY_SALARY * 0.6
        else: # Low previous bids
            if is_supply_tight:
                bid = max(DAILY_SALARY * 0.65, highest_prev_bid + 5)
            else:
                bid = DAILY_SALARY * 0.5

    # Critical HP overrides other logic
    if my_status['hp'] <= 3:
        bid = DAILY_SALARY * 0.95
    elif my_status['hp'] <= 5:
        bid = max(bid, DAILY_SALARY * 0.8)

    # If I missed water yesterday, ensure a strong bid for today
    if my_status['no_water_days'] > 0:
        if my_status['hp'] > 5:
            bid = max(bid, DAILY_SALARY * 0.7)
        else:
            bid = max(bid, DAILY_SALARY * 0.9)

    final_bid = min(my_status['budget'], bid)

    # Ensure a minimal bid if budget allows, to avoid bidding 0 when water is needed
    if final_bid <= 0 and my_status['budget'] > 0:
        final_bid = min(my_status['budget'], DAILY_SALARY * 0.1)

    return final_bid

